'use strict';
const $=id=>document.getElementById(id);
const fields=['deviceId','deviceName','fault','methods','status','next','checkDate'];
const KEY='repair-notebook-v1', DRAFT=KEY+'-draft';
let records=[],step=1,current=null, saved=false, storageOK=true, readBlocked=false;
const notify=message=>{$('notice').textContent=message;};
function readForm(){return Object.fromEntries(fields.map(k=>[k,$(k).value.trim()]));}
function validRecord(r){return r&&typeof r.id==='string'&&typeof r.created==='string'&&!isNaN(Date.parse(r.created))&&fields.every(k=>typeof r[k]==='string')&&r.deviceId.trim()&&r.fault.trim()&&['未解决','已解决','待观察'].includes(r.status)&&(!r.checkDate||/^\d{4}-\d{2}-\d{2}$/.test(r.checkDate));}
function persistDraft(){try{localStorage.setItem(DRAFT,JSON.stringify(readForm()));}catch{storageOK=false;notify('浏览器无法保存草稿。请保持页面打开，并下载小结或导出备份。');}}
function view(name){for(const id of ['editor','result','history'])$(id).hidden=id!==name;$('newTab').classList.toggle('active',name!=='history');$('historyTab').classList.toggle('active',name==='history');}
function go(n){step=n;for(let i=1;i<=3;i++){$('step'+i).hidden=i!==n;$('s'+i).classList.toggle('current',i===n);}$('prev').hidden=n===1;$('forward').textContent=n===3?'生成维修小结':'下一步';$('progress').textContent=`第 ${n} 步 / 共 3 步`;}
function stamp(r){return new Date(r.created).toLocaleString('zh-CN',{hour12:false});}
function summaryParts(r){return [['设备编号',r.deviceId],['设备名称',r.deviceName||'未填写'],['故障经过',r.fault],['试过的方法',r.methods||'未填写'],['当前状况',r.status],['下一步处理',r.next||'未定'],['下次检查时间',r.checkDate||'未定']];}
function renderResult(r,isSaved){current=r;saved=isSaved;view('result');$('resultTitle').textContent=r.deviceName?`${r.deviceId} · ${r.deviceName}`:r.deviceId;$('badge').textContent=r.status;$('recordTime').textContent='记录时间：'+stamp(r);$('summary').replaceChildren();for(const [title,value]of summaryParts(r)){const block=document.createElement('div');block.className='summaryblock';const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=value;block.append(h,p);$('summary').append(block);}$('save').disabled=isSaved;$('save').textContent=isSaved?'已保存到历史':'保存到历史';$('edit').hidden=isSaved;}
function renderHistory(){const q=$('search').value.trim().toLocaleLowerCase();$('count').textContent=records.length;const list=$('records');list.replaceChildren();const filtered=records.filter(r=>[r.deviceId,r.deviceName,r.fault,r.methods,r.next].some(v=>v.toLocaleLowerCase().includes(q))).sort((a,b)=>b.created.localeCompare(a.created));if(!filtered.length){const p=document.createElement('p');p.className='hint';p.textContent=records.length?'没有找到匹配记录，试试设备编号或其他关键词。':'还没有历史记录。填写三步并点击“保存到历史”后，会出现在这里。';list.append(p);}for(const r of filtered){const b=document.createElement('button');b.className='record';const title=document.createElement('strong');title.textContent=`${r.deviceId}${r.deviceName?' · '+r.deviceName:''}　｜${r.status}`;const time=document.createElement('small');time.textContent=stamp(r);const preview=document.createElement('span');preview.textContent=r.fault.slice(0,110)+(r.fault.length>110?'…':'');b.append(title,time,preview);b.onclick=()=>{renderResult(r,true);$('resultTitle').scrollIntoView({block:'start'});};list.append(b);}}
function commit(nextRecords){if(readBlocked){notify('原有数据读取失败，已停止写入以保护原始数据。请先保留备份，当前小结可以下载。');return false;}try{localStorage.setItem(KEY,JSON.stringify(nextRecords));records=nextRecords;storageOK=true;renderHistory();return true;}catch{notify('保存失败：浏览器存储不可用或空间不足。原有历史未改动；请下载当前小结或导出备份。');return false;}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('form').addEventListener('input',()=>{$('chars').textContent=`已填写 ${$('fault').value.length} 字`;persistDraft();});
$('form').addEventListener('submit',e=>{e.preventDefault();if(step===1){for(const id of ['deviceId','fault']){if(!$(id).value.trim()){notify('请填写设备编号和故障经过。');$(id).focus();return;}}}if(step<3){go(step+1);$('step'+step).querySelector('textarea,input,select').focus();}else{const r={...readForm(),id:globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2),created:new Date().toISOString()};renderResult(r,false);notify('小结已生成。请检查内容，再点击“保存到历史”。');}});
$('prev').onclick=()=>go(step-1);
$('edit').onclick=()=>{view('editor');go(3);};
$('newTab').onclick=()=>{view('editor');go(step);};
$('historyTab').onclick=()=>{renderHistory();view('history');};
$('search').oninput=renderHistory;
$('save').onclick=()=>{if(saved)return;if(commit([...records,current])){saved=true;$('save').disabled=true;$('save').textContent='已保存到历史';$('edit').hidden=true;try{localStorage.removeItem(DRAFT);}catch{}notify('已保存。这是独立的一次维修记录，不会覆盖同一设备的旧记录。');}};
$('another').onclick=()=>{if(!saved&&!confirm('这份小结尚未保存。确定放下它，开始新记录吗？'))return;$('form').reset();current=null;saved=false;persistDraft();$('chars').textContent='已填写 0 字';view('editor');go(1);notify('可以记录下一次维修；历史记录已保留。');};
$('sample').onclick=()=>{if(fields.some(k=>k!=='status'&&$(k).value)&&!confirm('使用演示样例会替换当前草稿，是否继续？'))return;$('form').reset();$('deviceId').value='D-01';$('deviceName').value='演示风扇';$('fault').value='启动后五秒停止。';$('methods').value='换插座后仍一样。';$('chars').textContent=`已填写 ${$('fault').value.length} 字`;persistDraft();notify('已填入合成演示样例，不代表实际设备。');};
$('download').onclick=()=>download('设备维修小结\n记录时间：'+stamp(current)+'\n\n'+summaryParts(current).map(([k,v])=>k+'\n'+v).join('\n\n'),'维修小结.txt','text/plain;charset=utf-8');
$('export').onclick=()=>download(JSON.stringify({format:KEY,records},null,2),'维修记录备份-'+new Date().toISOString().slice(0,10)+'.json','application/json');
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!==KEY||!Array.isArray(data.records)||!data.records.every(validRecord))throw Error();const merged=[...records];let added=0;for(const r of data.records){const existing=merged.find(x=>x.id===r.id);if(existing&&fields.every(k=>existing[k]===r[k])&&existing.created===r.created)continue;merged.push({...r,id:existing?r.id+'-import-'+Date.now()+'-'+added:r.id});added++;}if(commit(merged))notify(`备份已合并，新增 ${added} 条记录。`);}catch{notify('导入失败：请选择本页导出的有效 JSON 备份。现有记录未改变。');}finally{e.target.value='';}};
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(validRecord))throw Error();records=data;}const draft=JSON.parse(localStorage.getItem(DRAFT)||'null');if(draft&&fields.every(k=>typeof draft[k]==='string')){for(const k of fields)$(k).value=draft[k];notify('已恢复上次未完成的草稿。');}}catch{storageOK=false;readBlocked=true;notify('无法读取本机数据。请保留已有备份；可先填写并下载小结，暂勿保存或导入以免覆盖原始数据。');$('save').disabled=true;$('import').disabled=true;}
go(1);renderHistory();$('chars').textContent=`已填写 ${$('fault').value.length} 字`;

