'use strict';
const $=id=>document.getElementById(id);
const fields=['deviceId','deviceName','incident','attempts','condition','nextAction','checkAt'];
const KEY='repair-notebook-v1';
let db={records:[],draft:null},step=0,current=null,storageOK=true;
function message(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}
function validRecord(r){return r&&typeof r.id==='string'&&typeof r.createdAt==='string'&&!isNaN(Date.parse(r.createdAt))&&fields.every(k=>typeof r[k]==='string')&&r.deviceId.trim()&&r.incident.trim()&&['未解决','已解决','待观察'].includes(r.condition);}
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data.records)||!data.records.every(validRecord))throw Error();db=data;}}catch(e){storageOK=false;message('本机存储无法读取，已暂停写入以保护旧数据。可导入已有备份；本次小结仍可下载。',true);}
function persist(){if(!storageOK)return false;try{localStorage.setItem(KEY,JSON.stringify(db));return true;}catch(e){message('本机保存失败（空间不足或存储被禁用）。请下载小结并导出备份，暂勿关闭页面。',true);return false;}}
function values(){return Object.fromEntries(fields.map(k=>[k,$(k).value]));}
function fill(v){fields.forEach(k=>$(k).value=typeof v?.[k]==='string'?v[k]:(k==='condition'?'未解决':''));}
function draft(){db.draft=values();$('draftState').textContent=persist()?'草稿已暂存于此浏览器，重新打开可继续。':'草稿未能保存，请勿直接关闭页面。';}
function showStep(n){step=n;document.querySelectorAll('.step').forEach((el,i)=>el.hidden=i!==n);document.querySelectorAll('.steps li').forEach((el,i)=>{el.classList.toggle('active',i===n);if(i===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});$('prev').hidden=n===0;$('next').textContent=n===2?'保存并生成小结':'下一步';document.querySelectorAll('.step h2')[n].focus();}
function tab(history){$('editor').hidden=history||!!current;$('result').hidden=history||!current;$('history').hidden=!history;$('writeTab').setAttribute('aria-selected',String(!history));$('historyTab').setAttribute('aria-selected',String(history));if(history)renderHistory();}
function validate(){for(const key of ['deviceId','incident'])if(!$(key).value.trim()){showStep(0);message(key==='deviceId'?'请填写设备编号。':'请填写故障经过。',true);$(key).focus();return false;}return true;}
function dateText(value){return value?value.replace('T',' '):'未定';}
function parts(r){return [['设备',r.deviceId+(r.deviceName?' · '+r.deviceName:'')],['记录时间',new Date(r.createdAt).toLocaleString('zh-CN',{hour12:false})],['当前状况',r.condition],['故障经过',r.incident],['试过的方法',r.attempts.trim()?r.attempts:'未填写'],['下一步处理',r.nextAction.trim()?r.nextAction:'未定'],['下次检查时间',dateText(r.checkAt)]];}
function summaryInto(container,r){container.replaceChildren();for(const [label,value] of parts(r)){const h=document.createElement('h3');h.textContent=label;const p=document.createElement('p');p.className='text';p.textContent=value;container.append(h,p);}}
