$('prev').onclick=()=>showStep(step-1);
$('example').onclick=()=>{if(fields.some(k=>k!=='condition'&&$(k).value)&&!confirm('用演示样例替换当前草稿？'))return;fill({deviceId:'D-01',deviceName:'演示风扇',incident:'启动后五秒停止。',attempts:'换插座后仍一样。',condition:'未解决'});draft();showStep(0);};
$('clear').onclick=()=>{if(!confirm('清空本次草稿？已保存的维修记录不会删除。'))return;fill(null);db.draft=null;persist();showStep(0);$('draftState').textContent='草稿已清空。';};
$('writeTab').onclick=()=>tab(false);$('historyTab').onclick=()=>tab(true);
