$('download').onclick=()=>download(textSummary(current),'text/plain;charset=utf-8','维修小结-'+current.deviceId.replace(/[\\/:*?"<>|]/g,'_')+'.txt');
$('print').onclick=()=>window.print();
function renderHistory(){const q=$('search').value.trim().toLocaleLowerCase();const rows=db.records.filter(r=>(r.deviceId+' '+r.deviceName).toLocaleLowerCase().includes(q));$('records').replaceChildren();const count=document.createElement('p');count.className='muted';count.textContent=rows.length?'找到 '+rows.length+' 条维修记录':'暂无匹配记录。完成三步并保存后，这里会显示设备历史。';$('records').append(count);for(const r of rows){const d=document.createElement('details');const s=document.createElement('summary');s.textContent=r.deviceId+' · '+(r.deviceName||'未命名设备')+' ｜ '+r.condition+' ｜ '+new Date(r.createdAt).toLocaleString('zh-CN',{hour12:false});const body=document.createElement('div');summaryInto(body,r);const b=document.createElement('button');b.textContent='查看 / 下载小结';b.onclick=()=>showResult(r);body.append(b);d.append(s,body);$('records').append(d);}}
$('search').oninput=renderHistory;
$('backup').onclick=()=>download(JSON.stringify({version:1,records:db.records},null,2),'application/json','维修记录备份-'+new Date().toISOString().slice(0,10)+'.json');
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.records)||!data.records.every(validRecord))throw Error();const existing=new Map(db.records.map(r=>[r.id,r]));let added=0;for(const r of data.records){if(existing.has(r.id)){if(JSON.stringify(parts(existing.get(r.id)))!==JSON.stringify(parts(r)))throw Error('conflict');}else{existing.set(r.id,r);added++;}}db.records=[...existing.values()].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));const saved=persist();renderHistory();message('已导入 '+added+' 条新记录。'+(saved?'':'当前存储不可用，请导出合并后的备份。'),!saved);}catch(err){message(err.message==='conflict'?'导入取消：备份中有相同记录标识但内容不同，请保留原备份。':'导入失败：请选择本网页导出的有效 JSON 备份。原记录未改动。',true);}finally{e.target.value='';}};
if(db.draft){fill(db.draft);$('draftState').textContent='已恢复上次未完成的草稿。';}showStep(0);

