'use strict';
const $=id=>document.getElementById(id),KEY='repair-notebook-v1',DRAFT=KEY+'-draft';
const fields=['device','name','incident','methods','next','checkDate'];
let records=[],step=0,current=null,saved=false,storageOK=true;
function notice(text,error=false){$('message').textContent=text;$('message').className=error?'error':'';}
function read(){const d={};fields.forEach(k=>d[k]=$(k).value);d.state=document.querySelector('[name=state]:checked').value;return d;}
function fill(d){fields.forEach(k=>$(k).value=d[k]||'');document.querySelectorAll('[name=state]').forEach(e=>e.checked=e.value===(d.state||'未解决'));}
function validRecord(r){return r&&typeof r.id==='string'&&typeof r.created==='string'&&!isNaN(Date.parse(r.created))&&fields.every(k=>typeof r[k]==='string')&&r.device.trim()&&r.incident.trim()&&['未解决','已解决','待观察'].includes(r.state)&&(!r.checkDate||/^\d{4}-\d{2}-\d{2}$/.test(r.checkDate));}
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(validRecord))throw Error('invalid');records=data;}const draft=localStorage.getItem(DRAFT);if(draft)fill(JSON.parse(draft));}catch(e){storageOK=false;notice('无法读取本机数据。为避免覆盖已有内容，已暂停保存；您仍可填写并下载小结。请保留原浏览器数据。',true);}
function persistDraft(){if(!storageOK)return;try{localStorage.setItem(DRAFT,JSON.stringify(read()));$('draftNote').textContent='草稿已自动保存';}catch(e){$('draftNote').textContent='草稿未能保存，请下载小结';notice('浏览器存储不可用或空间不足，当前填写仍在页面中，请下载小结。',true);}}
function showStep(n){step=n;document.querySelectorAll('[data-step]').forEach(e=>e.hidden=+e.dataset.step!==n);document.querySelectorAll('.steps span').forEach((e,i)=>{e.classList.toggle('current',i===n);if(i===n)e.setAttribute('aria-current','step');else e.removeAttribute('aria-current');});$('prev').hidden=n===0;$('nextBtn').textContent=n===2?'生成维修小结 →':'下一步 →';}
function tab(history){$('editor').hidden=history;$('result').hidden=true;$('history').hidden=!history;$('writeTab').classList.toggle('active',!history);$('historyTab').classList.toggle('active',history);if(history)renderHistory();}
function validate(){for(const k of ['device','incident'])if(!$(k).value.trim()){showStep(0);notice(k==='device'?'请填写设备编号。':'请填写故障经过。',true);$(k).focus();return false;}if(!$('checkDate').validity.valid){showStep(2);notice('请填写有效的检查日期，或留空。',true);$('checkDate').focus();return false;}return true;}
function blocks(r){return [['故障经过',r.incident],['试过的方法',r.methods||'未记录'],['当前状况',r.state],['下一步处理',r.next||'未定'],['下次检查时间',r.checkDate||'未定']];}
function appendBlocks(target,r){blocks(r).forEach(([title,value])=>{const box=document.createElement('div');box.className='summary-block';const h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=value;box.append(h,p);target.append(box);});}
function summaryText(r){return `维修小结\n设备编号：${r.device}\n设备名称：${r.name||'未填写'}\n记录时间：${new Date(r.created).toLocaleString('zh-CN')}\n\n`+blocks(r).map(([k,v])=>k+'\n'+v).join('\n\n');}
function download(data,type,filename){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function updateCount(){$('count').textContent=records.length;}
function renderHistory(){updateCount();const q=$('search').value.trim().toLocaleLowerCase();const list=records.filter(r=>(r.device+' '+r.name).toLocaleLowerCase().includes(q)).slice().sort((a,b)=>b.created.localeCompare(a.created));$('records').replaceChildren();if(!list.length){const p=document.createElement('p');p.className='empty';p.textContent=q?'没有找到匹配设备，请试试其他编号或名称。':'还没有维修记录。完成三步后，点击“保存到设备历史”。';$('records').append(p);}list.forEach(r=>{const card=document.createElement('article');card.className='record';const title=document.createElement('h3');title.textContent=r.device+(r.name?' · '+r.name:'');const badge=document.createElement('span');badge.className='badge';badge.textContent=r.state;title.append(badge);const meta=document.createElement('p');meta.className='hint';meta.textContent=new Date(r.created).toLocaleString('zh-CN');const details=document.createElement('details'),s=document.createElement('summary');s.textContent='展开完整维修记录';details.append(s);appendBlocks(details,r);const reuse=document.createElement('button');reuse.textContent='为此设备新增记录';reuse.onclick=()=>{if(fields.some(k=>$(k).value)&&!confirm('当前草稿将被替换。是否继续为此设备新增记录？'))return;fill({device:r.device,name:r.name});persistDraft();showStep(0);tab(false);$('incident').focus();};card.append(title,meta,details,reuse);$('records').append(card);});}
$('form').addEventListener('input',persistDraft);
$('form').onsubmit=e=>{e.preventDefault();if(!validate())return;notice('');if(step<2){showStep(step+1);document.querySelector(`[data-step="${step}"] textarea`).focus();return;}current={...read(),device:$('device').value.trim(),id:globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2),created:new Date().toISOString()};saved=false;$('editor').hidden=true;$('result').hidden=false;$('resultTitle').textContent=current.device+(current.name?' · '+current.name:'');$('resultMeta').textContent='根据您的填写整理；当前尚未保存到历史。';$('summary').replaceChildren();appendBlocks($('summary'),current);$('save').hidden=false;$('backEdit').hidden=false;$('new').hidden=true;$('resultTitle').focus();};
$('prev').onclick=()=>showStep(Math.max(0,step-1));
$('backEdit').onclick=()=>{$('result').hidden=true;$('editor').hidden=false;showStep(2);};
$('save').onclick=()=>{if(saved||!current)return;if(!storageOK){notice('本机存储不可用，未保存。请下载小结。',true);return;}try{const updated=[...records,current];localStorage.setItem(KEY,JSON.stringify(updated));records=updated;saved=true;localStorage.removeItem(DRAFT);fill({});updateCount();$('save').hidden=true;$('backEdit').hidden=true;$('new').hidden=false;$('resultMeta').textContent='已保存到本机设备历史。';notice('保存成功。同一设备的旧记录仍然保留。');}catch(e){notice('保存失败，可能是浏览器空间不足。请下载小结，避免丢失。',true);}};
$('new').onclick=()=>{tab(false);showStep(0);$('device').focus();notice('');};
$('download').onclick=()=>{if(current)download(summaryText(current),'text/plain;charset=utf-8','维修小结.txt');};
$('writeTab').onclick=()=>{tab(false);showStep(step);};$('historyTab').onclick=()=>tab(true);$('search').oninput=renderHistory;
$('sample').onclick=()=>{if(fields.some(k=>$(k).value)&&!confirm('填入样例将替换当前草稿，是否继续？'))return;fill({device:'D-01',name:'演示风扇',incident:'启动后五秒停止。',methods:'换插座后仍一样。',state:'未解决'});showStep(0);persistDraft();notice('已填入合成演示样例，不是实际设备资料。');};
$('clearDraft').onclick=()=>{if(!confirm('清空当前未保存的草稿？已保存的历史记录不会删除。'))return;fill({});persistDraft();showStep(0);notice('草稿已清空。');};
$('export').onclick=()=>{download(JSON.stringify({format:'repair-notebook',version:1,records},null,2),'application/json','维修手记备份.json');notice('已发起备份下载，请在浏览器下载列表中确认文件。');};
$('import').onclick=()=>$('file').click();
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!storageOK)throw Error('本机存储不可用，无法导入。');const data=JSON.parse(await file.text());if(data.format!=='repair-notebook'||data.version!==1||!Array.isArray(data.records)||!data.records.every(validRecord))throw Error('备份格式不正确，未修改已有记录。');const seen=new Map(records.map(r=>[r.id,r]));let added=0;for(const r of data.records){if(seen.has(r.id)){if(JSON.stringify(seen.get(r.id))!==JSON.stringify(r))throw Error('备份中存在编号冲突，未导入。');continue;}seen.set(r.id,r);added++;}const merged=[...seen.values()];localStorage.setItem(KEY,JSON.stringify(merged));records=merged;renderHistory();notice(`导入完成，新增 ${added} 条记录；重复记录已跳过。`);}catch(err){notice('导入失败：'+err.message,true);}finally{e.target.value='';}};
showStep(0);updateCount();

