'use strict';
const $ = id => document.getElementById(id);
const RECORDS_KEY='xiuji.records.v1', DRAFT_KEY='xiuji.draft.v1';
const fields=['deviceId','deviceName','incident','methods','nextAction','checkAt'];
let records=[], step=0, savedId=null, savedTime=null, storageOK=true;
function notice(s=''){ $('notice').textContent=s; }
function read(key,fallback){try{const s=localStorage.getItem(key);return s?JSON.parse(s):fallback;}catch(e){storageOK=false;notice('无法读取本机数据，请先导出备份。仍可填写并下载小结。');return fallback;}}
function write(key,value){try{if(!storageOK)throw Error();localStorage.setItem(key,JSON.stringify(value));return true;}catch(e){notice('本机保存失败（可能是浏览器限制或空间不足）。内容仍在当前页面，请下载小结或导出备份。');return false;}}
function validRecord(r){return r&&typeof r.id==='string'&&r.id.length>0&&typeof r.createdAt==='string'&&!isNaN(Date.parse(r.createdAt))&&fields.every(f=>typeof r[f]==='string')&&r.deviceId.trim()&&r.incident.trim()&&['未解决','已解决','待观察'].includes(r.status);}
const stored=read(RECORDS_KEY,[]);
if(Array.isArray(stored)&&stored.every(validRecord))records=stored;else{storageOK=false;notice('历史数据格式异常，已停止写入以保护原数据。请保留浏览器数据，并使用已有备份恢复。');}
function data(){const d={};fields.forEach(f=>d[f]=$(f).value);d.status=document.querySelector('input[name=status]:checked').value;d.deviceId=d.deviceId.trim();return d;}
function fill(d){fields.forEach(f=>$(f).value=typeof d[f]==='string'?d[f]:'');document.querySelectorAll('input[name=status]').forEach(el=>el.checked=el.value===(d.status||'未解决'));}
function draft(){write(DRAFT_KEY,data());}
function show(view){['editor','result','history'].forEach(v=>$(v).hidden=v!==view);$('historyTab').classList.toggle('active',view==='history');$('newTab').classList.toggle('active',view!=='history');$('count').textContent=records.length;}
function go(n,focus=true){step=n;document.querySelectorAll('.step').forEach((el,i)=>el.hidden=i!==n);document.querySelectorAll('.steps li').forEach((el,i)=>{el.classList.toggle('current',i===n);if(i===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});$('prev').hidden=n===0;$('next').textContent=n===2?'生成维修小结 →':'下一步 →';$('progress').textContent=`第 ${n+1} 步，共 3 步`;if(focus)document.querySelectorAll('.step h2')[n].focus();}
function dateLabel(s){return s?s.replace('T',' '):'未定';}
function summaryParts(d){return [['设备编号',d.deviceId],['设备名称',d.deviceName||'未填写'],['故障经过',d.incident],['试过的方法',d.methods||'未填写'],['当前状况',d.status],['下一步处理',d.nextAction||'未定'],['下次检查时间',dateLabel(d.checkAt)]];}
function summaryText(d){return '维修小结\n'+summaryParts(d).map(([k,v])=>k+'：\n'+v).join('\n\n');}
function renderSummary(d){$('summary').replaceChildren();summaryParts(d).forEach(([k,v])=>{const h=document.createElement('h3'),p=document.createElement('p');h.textContent=k;p.textContent=v;$('summary').append(h,p);});}
function result(){renderSummary(data());$('save').disabled=!!savedId;$('edit').hidden=!!savedId;$('saveState').textContent=savedId?'已保存。本次记录已独立存入设备历史。':'请核对内容；点击“保存到设备历史”后才能在历史中查询。';show('result');$('result').querySelector('h2').focus();}
$('repairForm').addEventListener('submit',e=>{e.preventDefault();if(step===0&&(!$('deviceId').value.trim()||!$('incident').value.trim())){notice('请填写设备编号和故障经过，不能只填空格。');return;}notice();draft();if(step<2)go(step+1);else result();});
$('repairForm').addEventListener('input',()=>{savedId=null;savedTime=null;draft();});
$('prev').onclick=()=>go(step-1);
$('edit').onclick=()=>{show('editor');go(2);};
$('save').onclick=()=>{if(savedId)return;const r={...data(),id:crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2),createdAt:new Date().toISOString()};const next=[...records,r];if(write(RECORDS_KEY,next)){records=next;savedId=r.id;savedTime=r.createdAt;try{localStorage.removeItem(DRAFT_KEY);}catch{}result();}};
function fresh(){if(!savedId&&fields.some(f=>$(f).value)&&!confirm('开始新记录会清空当前未保存的填写内容，确定继续？'))return;fill({});savedId=null;savedTime=null;draft();show('editor');go(0);notice();}
$('another').onclick=fresh;
$('newTab').onclick=()=>{show(savedId?'result':'editor');};
$('sample').onclick=()=>{if(fields.some(f=>$(f).value)&&!confirm('示例会替换当前未保存的填写内容，确定继续？'))return;fill({deviceId:'D-01',deviceName:'演示风扇',incident:'启动后五秒停止。',methods:'换插座后仍一样。',status:'未解决'});savedId=null;draft();go(0);notice('已填入合成示例，可以修改后继续。');};
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function filename(s){return s.replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,60)||'设备';}
$('download').onclick=()=>download(summaryText(data()),'text/plain;charset=utf-8',filename(data().deviceId)+'-维修小结.txt');
function renderHistory(){const q=$('search').value.trim().toLocaleLowerCase();const list=records.filter(r=>[...fields.map(f=>r[f]),r.status].join('\n').toLocaleLowerCase().includes(q)).slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('records').replaceChildren();if(!list.length){const p=document.createElement('p');p.className='empty';p.textContent=records.length?'没有找到匹配记录，试试其他编号或关键词。':'还没有维修记录。完成三步并保存后，会显示在这里。';$('records').append(p);}list.forEach(r=>{const box=document.createElement('section');box.className='record';const h=document.createElement('h3');h.textContent=r.deviceId+' · '+(r.deviceName||'未命名设备');const meta=document.createElement('p');meta.className='meta';meta.textContent=new Date(r.createdAt).toLocaleString('zh-CN')+' · '+r.status;const details=document.createElement('details'),toggle=document.createElement('summary');toggle.textContent='查看完整维修小结';details.append(toggle);summaryParts(r).forEach(([k,v])=>{const p=document.createElement('p');p.textContent=k+'：\n'+v;details.append(p);});const exportBtn=document.createElement('button');exportBtn.textContent='下载此条小结';exportBtn.onclick=()=>download(summaryText(r),'text/plain;charset=utf-8',filename(r.deviceId)+'-维修小结.txt');box.append(h,meta,details,exportBtn);$('records').append(box);});$('count').textContent=records.length;}
$('historyTab').onclick=()=>{renderHistory();show('history');};$('search').oninput=renderHistory;
$('backup').onclick=()=>download(JSON.stringify({format:'xiuji-backup',version:1,records},null,2),'application/json','修记备份-'+new Date().toISOString().slice(0,10)+'.json');
$('restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const b=JSON.parse(await file.text());if(b.format!=='xiuji-backup'||b.version!==1||!Array.isArray(b.records)||!b.records.every(validRecord))throw Error('备份格式不正确，未导入任何记录。');const map=new Map(records.map(r=>[r.id,r]));for(const r of b.records){if(map.has(r.id)&&JSON.stringify(map.get(r.id))!==JSON.stringify(r))throw Error('备份含有编号冲突的记录，未导入。请保留两份备份。');map.set(r.id,r);}const next=[...map.values()];if(write(RECORDS_KEY,next)){const added=next.length-records.length;records=next;renderHistory();notice(`恢复完成，新增 ${added} 条记录。`);}}catch(err){notice(err instanceof SyntaxError?'文件不是有效的 JSON 备份，未导入任何记录。':err.message);}finally{e.target.value='';}};
const oldDraft=read(DRAFT_KEY,null);if(oldDraft&&typeof oldDraft==='object')fill(oldDraft);go(0,false);show('editor');

