'use strict';
const $ = id => document.getElementById(id);
const fields = ['deviceId','deviceName','incident','methods','status','next','checkDate'];
const KEY = 'xiuji-records-v1', DRAFT = 'xiuji-draft-v1';
let records = [], step = 0, selected = null, saved = false, storageOK = true;
function notify(s) { $('notice').textContent = s; }
function read(key, fallback) { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : fallback; } catch(e) { storageOK = false; notify('本地保存不可用或数据无法读取。请先导出备份，勿关闭页面。'); return fallback; } }
function persist(key, value) { if (!storageOK) return false; try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch(e) { storageOK = false; notify('本地保存失败（可能空间不足）。请导出备份，勿关闭页面。'); return false; } }
function data() { return Object.fromEntries(fields.map(k => [k, $(k).value])); }
function fill(d) { fields.forEach(k => $(k).value = d[k] || (k === 'status' ? '未解决' : '')); count(); }
function count() { $('count').textContent = `已写 ${Array.from($('incident').value).length} 字，不限制篇幅`; }
function showStep(n) { step = n; document.querySelectorAll('[data-step]').forEach((el,i) => el.hidden = i !== n); document.querySelectorAll('.steps span').forEach((el,i) => { el.classList.toggle('active',i===n); if(i===n) el.setAttribute('aria-current','step'); else el.removeAttribute('aria-current'); }); $('prev').hidden = n===0; $('nextStep').hidden=n===2; $('save').hidden=n!==2; $('error').textContent=''; }
function valid() { for(const k of ['deviceId','incident']) if(!$(k).value.trim()) { showStep(0); $('error').textContent = k==='deviceId' ? '请填写设备编号，方便以后查找。' : '请填写故障经过。'; $(k).focus(); return false; } return true; }
function draft() { saved=false; count(); const ok=persist(DRAFT,data()); $('draftState').textContent=ok?'草稿已自动保存，可放心返回上一步。':'草稿未保存，请导出备份后再关闭页面。'; }
function stamp(s) { return new Date(s).toLocaleString('zh-CN',{hour12:false}); }
function parts(r) { return [['设备编号',r.deviceId],['设备名称',r.deviceName||'未填写'],['故障经过',r.incident],['试过的方法',r.methods||'未填写'],['当前状况',r.status],['下一步处理',r.next||'未定'],['下次检查时间',r.checkDate?r.checkDate.replace('T',' '):'未定']]; }
function summaryText(r) { return '维修小结\n记录时间：'+stamp(r.createdAt)+'\n\n'+parts(r).map(([k,v])=>k+'\n'+v).join('\n\n'); }
function showResult(r) { selected=r; $('result').hidden=false; $('resultMeta').textContent='记录时间：'+stamp(r.createdAt); $('summary').replaceChildren(); for(const [k,v] of parts(r)) { const h=document.createElement('h3'),p=document.createElement('p'); h.textContent=k;p.textContent=v;p.className='text';$('summary').append(h,p); } $('result').scrollIntoView({behavior:'smooth'}); $('resultHeading').focus({preventScroll:true}); }
function history() { const q=$('search').value.trim().toLocaleLowerCase(); const list=records.filter(r=>(r.deviceId+' '+r.deviceName).toLocaleLowerCase().includes(q)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)); $('total').textContent=`共 ${records.length} 条记录，当前显示 ${list.length} 条`; $('history').replaceChildren(); if(!list.length) { const p=document.createElement('p');p.className='muted';p.textContent=q?'没有找到，试试设备编号。':'还没有记录，完成左侧三步即可保存。';$('history').append(p); } list.forEach(r=>{const b=document.createElement('button'),s=document.createElement('small');b.type='button';b.textContent=r.deviceId+(r.deviceName?' · '+r.deviceName:'');s.textContent=stamp(r.createdAt)+' · '+r.status;b.append(s);b.onclick=()=>showResult(r);$('history').append(b);}); }
function download(name,text,type) { const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function reset() { fill({});saved=false;showStep(0);persist(DRAFT,data());$('result').hidden=true;$('deviceId').focus();$('draftState').textContent='已开始新的草稿。历史记录仍可查询。'; }
function validRecord(r) { return r && typeof r.id==='string' && typeof r.createdAt==='string' && !isNaN(Date.parse(r.createdAt)) && fields.every(k=>typeof r[k]==='string') && r.deviceId.trim() && r.incident.trim() && ['未解决','已解决','待观察'].includes(r.status) && (!r.checkDate || /^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(r.checkDate)); }
const loaded=read(KEY,[]); if(Array.isArray(loaded)&&loaded.every(validRecord)) records=loaded; else { storageOK=false;notify('历史数据格式异常，已停止写入以保护原数据。'); }
const restored=read(DRAFT,null); if(restored&&fields.every(k=>typeof restored[k]==='string')) { fill(restored);$('draftState').textContent='已恢复上次未完成的草稿。'; }
$('form').addEventListener('input',draft);$('form').addEventListener('change',draft);
$('nextStep').onclick=()=>{if(valid()) {showStep(step+1);document.querySelector(`[data-step="${step}"] textarea`).focus();}};
$('prev').onclick=()=>showStep(step-1);
$('form').onsubmit=e=>{e.preventDefault();if(!valid())return;if(step!==2){showStep(step+1);return;}if(saved){notify('这份记录已经保存。如需追加一次维修，请点“再记一次”。');return;}const r={...data(),deviceId:$('deviceId').value.trim(),id:globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2),createdAt:new Date().toISOString()};records.push(r);saved=true;const ok=persist(KEY,records);if(ok)try{localStorage.removeItem(DRAFT);}catch(e){}history();showResult(r);notify(ok?'维修记录已保存，可在设备历史中重新查看。':'小结已生成，但未能写入本地。请立即导出全部备份。');$('draftState').textContent=ok?'本次记录已保存。继续修改后保存，会新增一条记录。':'本次记录尚未保存到浏览器。';};
$('sample').onclick=()=>{if(fields.some(k=>k!=='status'&&$(k).value)&&!confirm('用合成样例替换当前草稿？已保存的历史不受影响。'))return;fill({deviceId:'D-01',deviceName:'演示风扇',incident:'启动后五秒停止。',methods:'换插座后仍一样。',status:'未解决'});showStep(0);draft();notify('已填入合成样例，尚未保存为维修记录。');};
